#include <stdio.h>

#define MAXN 100

int main(void) {
    int a[MAXN], n, i, t;

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 1;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    for (i = 0; i < n / 2; i++) {
        t = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = t;
    }
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}
```
