problems.solution:
#include <stdio.h>

#define MAXSIZE 100

typedef struct {
    int data[MAXSIZE];
    int length;
} SqList;

/* 在顺序表 L 的第 i 个位序（1 <= i <= length+1）前插入 e，成功返回 1，失败返回 0 */
int ListInsert(SqList *L, int i, int e) {
    int j;

    if (i < 1 || i > L->length + 1)
        return 0;
    if (L->length >= MAXSIZE)
        return 0;
    for (j = L->length; j >= i; j--)
        L->data[j] = L->data[j - 1];
    L->data[i - 1] = e;
    L->length++;
    return 1;
}

int main(void) {
    SqList L;
    int n, i, x, e, j, ok;

    L.length = 0;
    if (scanf("%d", &n) != 1 || n < 0 || n > MAXSIZE)
        return 1;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &x) != 1)
            return 1;
