problems.stem:
下面的程序先建一条单链表 1→2→3→4→5，然后从标准输入读入两个整数 key 与 x，
在第一个值为 key 的结点之后插入值为 x 的新结点（找不到 key 就不插），最后按次序打印整条链。
程序能编译通过、也能跑出结果，但输出是错的。请找出错误并改正。

```c
#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int data; struct Node *next; } Node;
/* 尾插法建一条 1->2->3->4->5 的单链表 */
static Node *buildList(void)
{
    Node *head = NULL, *tail = NULL;
    int i;
    for (i = 1; i <= 5; i++) {
        Node *p = (Node *)malloc(sizeof(Node));
        p->data = i; p->next = NULL;
        if (tail == NULL) head = tail = p;
        else { tail->next = p; tail = p; }
    }
    return head;
}
/* 在第一个值为 key 的结点之后插入 x；找不到 key 就不插 */
static void insertAfter(Node *head, int key, int x)
{
    Node *p = head, *s;
    while (p != NULL && p->data != key) p = p->next;
    if (p == NULL) return;
    s = (Node *)malloc(sizeof(Node));
    s->data = x;
    p->next = s;
    s->next = NULL;
}
int main(void)
{
    int key, x; Node *head, *p;
    if (scanf("%d %d", &key, &x) != 2) return 1;
    head = buildList();
    insertAfter(head, key, x);
    for (p = head; p != NULL; p = p->next) {
        if (p != head) printf(" ");
        printf("%d", p->data);
    }
    printf("\n");
    return 0;
}
```

