    printf("删掉了 %d 个元素，做了 %d 次关键字比较（表长 %d，扫描了 %d 个）\n", removed, cmp, n, n > 1 ? n - 1 : 0);
    printf("自检：去重后严格递增 ? %d；原表的每个不同值都还在 ? %d；len + removed == n ? %d\n",
           strictlyUp(&L), allKept, L.len + removed == n);
