    h->data = 0; h->next = NULL;
    for (i = 0; i < n; i++) { s = (LNode *)malloc(sizeof(LNode));
        s->data = a[i]; s->next = NULL; t->next = s; t = s; }
    return h; }
static int listLen(LinkList L) { LNode *p = L->next; int c = 0; while (p != NULL) { c++; p = p->next; } return c; }
